html:
{% set audit = frappe.get_doc("Audit Office for Certifications", doc.audit_office) if doc.audit_office else None %}
{% set date_str = frappe.format_date(doc.date) %}

<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head>
  <meta charset="utf-8" />
  <meta http-equiv="Content-Type" content="text/html; charset=UTF-8">
  <style type="text/css">
    /* Reset and Base Settings for wkhtmltopdf */
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }

    /* Page Settings for wkhtmltopdf */
    @page {
      size: A4;
      margin: 0;
    }

    @media print {
      html, body {
        width: 210mm;
        height: 297mm;
        margin: 0;
        padding: 0;
      }
    }

    html {
      font-size: 14px;
      -webkit-text-size-adjust: 100%;
      margin: 0;
      padding: 0;
      width: 100%;
    }

    body {
      margin: 0;
      padding: 10mm;
      width: 100%;
      min-height: 297mm;
      direction: rtl;
      text-align: right;
      font-family: "Arial", "Tahoma", sans-serif;
      font-size: 14px;
      line-height: 1.6;
      color: #000000;
      background-color: #ffffff;
      display: block;
    }

    /* Container */
    .page {
      width: 100%;
      margin: 0;
      padding: 0;
      background-color: #ffffff;
      page-break-after: always;
      display: block;
      position: relative;
    }

    .page:last-child {
      page-break-after: auto;
    }

    /* Header Styles */
    .header {
      text-align: center;
      padding: 12px;
      margin-bottom: 12px;
      border: 2px solid #000000;
      background-color: #ffffff;
      page-break-inside: avoid;
      width: 100%;
    }

    .company-info {
      margin-bottom: 10px;
      padding-bottom: 10px;
      border-bottom: 2px solid #000000;
      width: 100%;
    }

    .company-name {
      font-size: 22px;
      font-weight: bold;
      margin-bottom: 8px;
      color: #000000;
    }

    .company-details-table {
      width: 100%;
      margin: 8px auto;
      table-layout: fixed;
    }

    .company-details-row {
      text-align: center;
      font-size: 12px;
      color: #333333;
    }

    .company-details-row td {
      padding: 2px 8px;
      vertical-align: middle;
      text-align: center;
    }

    .detail-label {
      font-weight: bold;
      color: #000000;
    }

    .detail-separator {
      color: #999999;
      padding: 0 5px;
    }

    .main-title {
      font-size: 20px;
      font-weight: bold;
      margin: 10px 0 8px 0;
      color: #000000;
    }

    .date-info {
      display: inline-block;
      font-size: 14px;
      font-weight: bold;
      padding: 4px 15px;
      border: 1px solid #666666;
      background-color: #ffffff;
    }

    /* Content Box */
    .content-box {
      background-color: #ffffff;
      border: 1px solid #999999;
      padding: 12px;
      margin-bottom: 12px;
      page-break-inside: avoid;
      width: 100%;
    }

    .customer-greeting {
      font-size: 14px;
      margin-bottom: 10px;
      padding: 8px 10px;
      background-color: #f5f5f5;
      border-right: 3px solid #333333;
    }

    .customer-name {
      color: #000000;
      font-weight: bold;
      font-size: 15px;
    }

    .greeting-text {
      text-align: center;
      font-style: italic;
      margin: 10px 0;
      color: #333333;
      font-size: 13px;
    }

    /* Balance Section */
    .balance-section {
      border: 2px solid #000000;
      padding: 12px;
      margin: 15px 0;
      text-align: center;
      background-color: #fafafa;
      page-break-inside: avoid;
    }

    .balance-label {
      font-size: 13px;
      margin-bottom: 8px;
      color: #333333;
    }

    .balance-amount {
      font-size: 22px;
      font-weight: bold;
      margin: 8px 0;
      color: #000000;
      direction: ltr;
      unicode-bidi: embed;
    }

    .balance-words {
      font-style: italic;
      font-size: 12px;
      margin-top: 8px;
      color: #555555;
      direction: ltr;
      unicode-bidi: embed;
    }

    /* Instruction Text */
    .instruction-text {
      margin: 10px 0;
      line-height: 1.8;
      color: #000000;
      padding: 10px;
      background-color: #f8f8f8;
      border-right: 3px solid #666666;
      font-size: 12px;
    }

    /* Audit Info */
    .audit-info {
      background-color: #f5f5f5;
      border: 1px solid #999999;
      padding: 10px;
      margin: 10px 0;
      color: #000000;
      font-size: 11px;
      line-height: 1.8;
      page-break-inside: avoid;
    }

    .audit-office {
      font-weight: bold;
      color: #000000;
    }

    .closing-text {
      text-align: center;
      font-weight: bold;
      margin: 15px 0 10px 0;
      color: #000000;
      font-size: 14px;
    }

    /* Utility Classes */
    .text-center { text-align: center; }
    .text-right { text-align: right; }
    .bold { font-weight: bold; }
    .mb-10 { margin-bottom: 10px; }

    /* wkhtmltopdf specific fixes */
    table {
      border-collapse: collapse;
      border-spacing: 0;
    }

    /* Prevent content overflow */
    .page * {
      word-wrap: break-word;
      overflow-wrap: break-word;
    }

    /* Clear floats */
    .clearfix:after {
      content: "";
      display: table;
      clear: both;
    }
  </style>
</head>
<body>

{% for row in doc.customer_balance %}
  {% set currency = row.currency or doc.currency or "SAR" %}
  {% set balance = (row.balance or 0) | float %}
  {% set formatted_balance = "{:,.2f}".format(balance) %}
  {% set customer_vat_reg_no = frappe.db.get_value("Customer", row.customer, 'custom_vat_registration_number') %}
  {% set buyer_address = row.customer_address if row.get('customer_address') else None %}
  {% if buyer_address %}
    {% set buyer_street, buyer_city, buyer_district, buyer_postal_code = frappe.db.get_value(
        'Address',
        buyer_address,
        ["address_line1", "city", "state", "pincode"]
    ) %}
  {% else %}
    {% set buyer_street, buyer_city, buyer_district, buyer_postal_code = None, None, None, None %}
  {% endif %}

  <div class="page">
    <!-- Header Section -->
    <div class="header">
      <div class="company-info">
        <div class="company-name">شركة نكهة المشروب للتجارة</div>
        <table class="company-details-table" align="center" cellpadding="0" cellspacing="0">
          <tr class="company-details-row">
            <td style="text-align: center; width: 100%;">
              <span class="detail-label">الرقم الضريبي:</span> 311003515800003
              <span class="detail-separator">|</span>
              <span class="detail-label">السجل التجاري:</span> 1010598153
            </td>
          </tr>
        </table>
      </div>
      <h1 class="main-title">مطابقة رصيد العميل</h1>
      <div class="date-info">{{ date_str }}</div>
    </div>

    <!-- Content Section -->
    <div class="content-box">
      <div class="customer-greeting">
        السادة / <span class="customer-name">{{ row.customer_name or row.customer }}</span>
        {% if buyer_street or buyer_city or buyer_district %}
          <div style="font-size: 11px; margin-top: 4px; color: #555555;">
            {% if buyer_street %}{{ buyer_street }}{% endif %}
            {% if buyer_city %}{% if buyer_street %}, {% endif %}{{ buyer_city }}{% endif %}
            {% if buyer_district %}{% if buyer_street or buyer_city %}, {% endif %}{{ buyer_district }}{% endif %}
            {% if buyer_postal_code %} - {{ buyer_postal_code }}{% endif %}
          </div>
        {% endif %}
        {% if customer_vat_reg_no %}
          <div style="font-size: 11px; margin-top: 4px; color: #555555;">
            <span class="detail-label">الرقم الضريبي:</span> {{ customer_vat_reg_no }}
          </div>
        {% endif %}
      </div>

      <div class="greeting-text">بعد التحية،</div>

      <div class="balance-section">
        <div class="balance-label">
          نود أن نفيدكم أن رصيدكم لدينا حتى تاريخ <strong>{{ date_str }}</strong>
        </div>
        <div class="balance-amount">{{ formatted_balance }} {{ currency }}</div>
        <div class="balance-words">({{ frappe.utils.money_in_words(balance, currency) }})</div>
      </div>

      <div class="instruction-text">
        للتحقق من صحة هذا الرصيد نرجو مراجعته مع سجلاتكم وإرسال مصادقتكم مباشرة إلى مراجعي حساباتنا.
      </div>

      {% if audit %}
      <div class="audit-info">
        <div class="mb-10">
          السادة / <span class="audit-office">{{ audit.office_name }}</span>، وذلك باستكمال الجزء السفلي من هذا الخطاب.
        </div>
        <div>
          ترسل المصادقة إلى السادة / {{ audit.office_name }}
          على عنوان بريد:
          {% if audit.postal_address %}، {{ audit.postal_address }}{% endif %}
          {% if audit.e_mail %}، أو عبر البريد الإلكتروني {{ audit.e_mail }}{% endif %}
          {% if audit.fax %}، أو على الفاكس {{ audit.fax }}{% endif %}
          ، في أقرب وقت ممكن.
        </div>
      </div>
      {% endif %}

      <div class="closing-text">وتفضلوا بقبول فائق الاحترام،</div>
    </div>
  </div>

{% endfor %}

</body>
</html>
